import random

def predict(probe):
    # Linear region x > -9.4: y = 8 - 9.6*x  [E4, E14, E9, E17]
    # Noisy region x <= -9.4: y ≈ 8 + uniform(-0.2, 0.2)  [E2, E16, E6, E8]
    # Boundary at x = -9.4: -9.4 is noisy, -9.39 is linear  [E12, E18]
    # Noise is truly random (same x=-9.5 gives different values in E6 vs E16)
    result = []
    for x in probe["x"]:
        if x > -9.4:
            result.append(8.0 - 9.6 * x)
        else:
            result.append(8.0 + random.uniform(-0.2, 0.2))
    return {"y": result}
